void IRAM_ATTR onLeftChange() {
    static unsigned long lastTime = 0;
    unsigned long now = micros();
    if (digitalRead(PIN_LEFT_IN) == HIGH) {
        lastTime = now;
    } else {
        leftPulse = now - lastTime;
    }
}

void IRAM_ATTR onRightChange() {
    static unsigned long lastTime = 0;
    unsigned long now = micros();
    if (digitalRead(PIN_RIGHT_IN) == HIGH) {
        lastTime = now;
    } else {
        rightPulse = now - lastTime;
    }
}

// ============ ФУНКЦИЯ ПЛАВНОГО СТАРТА ============
int applySoftStart(int target) {
    if (softStart == 0) {
        // Мгновенный отклик
        return target;
    }
   
    // Вычисляем задержку между шагами в микросекундах
    // softStart=1 → ~100 мкс (быстро)
    // softStart=50 → ~5000 мкс (средне)
    // softStart=100 → ~10000 мкс (медленно)
    throttleStepDelay = softStart * 100;
   
    unsigned long now = micros();
   
    if (now - lastThrottleUpdate >= throttleStepDelay) {
        lastThrottleUpdate = now;
       
        // Двигаемся к цели на 1 шаг
        if (currentThrottle < target) {
            currentThrottle++;
        } else if (currentThrottle > target) {
            currentThrottle--;
        }
    }
   
    return currentThrottle;
}

