void handleSet() {
    if (server.hasArg("trim")) {
        rudderTrim = server.arg("trim").toInt();
        rudderTrim = constrain(rudderTrim, -200, 200);
    }
    if (server.hasArg("scale")) {
        steeringScale = server.arg("scale").toInt();
        steeringScale = constrain(steeringScale, 1, 4);
    }
    if (server.hasArg("thrlimit")) {
        throttleLimit = server.arg("thrlimit").toInt();
        throttleLimit = constrain(throttleLimit, 100, 500);
    }
    if (server.hasArg("softstart")) {
        softStart = server.arg("softstart").toInt();
        softStart = constrain(softStart, 0, 100);
    }
    if (server.hasArg("invrudder")) {
        reverseRudder = server.arg("invrudder") == "1";
    }
    if (server.hasArg("invthr")) {
        reverseThrottle = server.arg("invthr") == "1";
    }
    if (server.hasArg("save")) {
        saveSettings();
    }
    if (server.hasArg("reset")) {
        resetSettings();
    }
    server.send(200, "text/plain", "OK");
}

void handleStatus() {
    unsigned long L = (leftPulse > 0) ? leftPulse : CENTER;
    unsigned long R = (rightPulse > 0) ? rightPulse : CENTER;
   
    String json = "{";
    json += "\"left\":" + String(L) + ",";
    json += "\"right\":" + String(R) + ",";
    json += "\"throttle\":" + String(currentThrottle) + ",";
    json += "\"rudder\":" + String(rudder.readMicroseconds()) + ",";
    json += "\"trim\":" + String(rudderTrim) + ",";
    json += "\"softstart\":" + String(softStart) + ",";
    json += "\"scale\":" + String(steeringScale) + ",";
    json += "\"thrlimit\":" + String(throttleLimit) + ",";
    json += "\"invrudder\":" + String(reverseRudder ? "true" : "false") + ",";
    json += "\"invthr\":" + String(reverseThrottle ? "true" : "false");
    json += "}";
   
    server.send(200, "application/json", json);
}

