    attachInterrupt(digitalPinToInterrupt(PIN_LEFT_IN), onLeftChange, CHANGE);
    attachInterrupt(digitalPinToInterrupt(PIN_RIGHT_IN), onRightChange, CHANGE);
   
    esc.attach(PIN_ESC_OUT, MIN_PULSE, MAX_PULSE);
    rudder.attach(PIN_SERVO_OUT, MIN_PULSE, MAX_PULSE);
   
    esc.writeMicroseconds(CENTER);
    rudder.writeMicroseconds(CENTER);
    currentThrottle = CENTER;
   
    // Загружаем сохранённые настройки
    loadSettings();
   
    // Запускаем Wi-Fi точку доступа
    WiFi.softAP(ssid, password);
    Serial.println();
    Serial.print("IP адрес: ");
    Serial.println(WiFi.softAPIP());
   
    // Настраиваем OTA
    setupOTA();
   
    // Запускаем веб-сервер
    server.on("/", handleRoot);
    server.on("/set", handleSet);
    server.on("/status", handleStatus);
    server.begin();
   
    Serial.println("Веб-сервер запущен");
    Serial.println("Подключитесь к Wi-Fi: " + String(ssid));
    Serial.println("Откройте в браузере: http://" + WiFi.softAPIP().toString());
    Serial.println("OTA пароль: " + String(ota_password));
}

// ============ LOOP ============
void loop() {
    ArduinoOTA.handle();
    server.handleClient();
   
    // Обработка ШИМ сигналов
    unsigned long L = (leftPulse > 0) ? leftPulse : CENTER;
    unsigned long R = (rightPulse > 0) ? rightPulse : CENTER;
   
    L = constrain(L, (unsigned long)MIN_PULSE, (unsigned long)MAX_PULSE);
    R = constrain(R, (unsigned long)MIN_PULSE, (unsigned long)MAX_PULSE);
   
    // ===== ВЫЧИСЛЕНИЕ ЦЕЛЕВОГО ГАЗА =====
    targetThrottle = (L + R) / 2;
   
    if (abs(targetThrottle - CENTER) < DEADBAND) {
        targetThrottle = CENTER;
    }
   
    // Ограничение газа
    if (targetThrottle > CENTER + throttleLimit) targetThrottle = CENTER + throttleLimit;
    if (targetThrottle < CENTER - throttleLimit) targetThrottle = CENTER - throttleLimit;
   
    // Инверсия газа
    if (reverseThrottle) {
        targetThrottle = CENTER - (targetThrottle - CENTER);
    }
   
    // ===== ПРИМЕНЕНИЕ ПЛАВНОГО СТАРТА =====
    int finalThrottle = applySoftStart(targetThrottle);
   
    // ===== ВЫЧИСЛЕНИЕ РУЛЯ =====
    int steering = (int)L - (int)R;
    int rudderSignal = CENTER + rudderTrim + (steering / steeringScale);
   
    // Ограничение руля
    if (rudderSignal > CENTER + rudderLimit) rudderSignal = CENTER + rudderLimit;
    if (rudderSignal < CENTER - rudderLimit) rudderSignal = CENTER - rudderLimit;
   
    // Инверсия руля
    if (reverseRudder) {
        rudderSignal = CENTER - (rudderSignal - CENTER);
    }
   
    // Финальные ограничения
    rudderSignal = constrain(rudderSignal, servoMin, servoMax);
    finalThrottle = constrain(finalThrottle, MIN_PULSE, MAX_PULSE);
   
    // ===== ОТПРАВКА СИГНАЛОВ =====
    esc.writeMicroseconds(finalThrottle);
    rudder.writeMicroseconds(rudderSignal);
   
    delay(5);
}
